package com.mlay.animedownloader;
import android.app.*;import android.content.Intent;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import java.util.*;
public class MediaBrowserActivity extends Activity{
 private LinearLayout found; private final MediaDetector detector=new MediaDetector();
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xff08090f);EditText address=new EditText(this);address.setHint("Adresse d’une page autorisée");address.setSingleLine();address.setTextColor(0xffffffff);address.setHintTextColor(0xffaaaec0);root.addView(address,new LinearLayout.LayoutParams(-1,56));found=new LinearLayout(this);found.setOrientation(LinearLayout.VERTICAL);root.addView(found);WebView web=new WebView(this);WebSettings w=web.getSettings();w.setJavaScriptEnabled(true);w.setDomStorageEnabled(true);w.setMediaPlaybackRequiresUserGesture(false);web.setWebChromeClient(new WebChromeClient());web.setWebViewClient(detector.client((url,type)->runOnUiThread(()->add(url,type))));root.addView(web,new LinearLayout.LayoutParams(-1,0,1));address.setOnEditorActionListener((v,a,e)->{String u=address.getText().toString().trim();if(!u.startsWith("http"))u="https://"+u;web.loadUrl(u);return true;});setContentView(root);}
 private void add(String url,String type){Button b=new Button(this);b.setText(type+" détecté • Télécharger");b.setOnClickListener(v->{String ext=type.equals("MP4")?".mp4":type.equals("WEBM")?".webm":".m3u8";if(type.equals("HLS")){Toast.makeText(this,"Flux HLS détecté. Le moteur de sauvegarde HLS n’est pas encore disponible.",Toast.LENGTH_LONG).show();}else{DownloadQueue.add(this,url,"Média détecté","SOURCE","kaze_"+System.currentTimeMillis()+ext);Toast.makeText(this,"Téléchargement ajouté",Toast.LENGTH_SHORT).show();}});found.addView(b,new LinearLayout.LayoutParams(-1,64));}
}
